    {
      "lemma": "property lemma_2; @(posedge clk) (count < 5'd16) |-> !busy[alloc_addr]; endproperty",
      "explanation": "Given the occupancy invariant, a count below 16 means a free entry exists. The priority encoder selects one, supplying the allocation-side fact needed to prove lemma_1 inductively."
    }
  ]
}
</json>

